messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            font-family: Arial, sans-serif;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 1px 1px 2px black;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Press SPACE to Reset</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = 0;
        const START_Z = -100;
        const CAMERA_HEIGHT = 45;
        const CAMERA_DISTANCE = 30;
        const CAMERA_X = 0;
        const CAR_SIZE = 4;
        const SPEED_LIMIT = 1.5;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(CAMERA_X, CAMERA_HEIGHT, CAMERA_DISTANCE);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        scene.add(dirLight);

        // --- Track ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Start Line
        const startLineGeo = new THREE.PlaneGeometry(20, 2);
        const startLineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const startLine = new THREE.Mesh(startLineGeo, startLineMat);
        startLine.rotation.x = -Math.PI / 2;
        startLine.position.set(0, 0.05, START_Z);
        scene.add(startLine);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(20, 2);
        const finishLineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.05, FINISH_LINE_Z);
        scene.add(finishLine);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Main Body
            const bodyGeo = new THREE.BoxGeometry(CAR_SIZE, 1.5, 3);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 1.5;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(CAR_SIZE - 0.5, 1, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 2.8;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.8, 0.8, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1.5, z: 1.2 }, { x: 1.5, z: 1.2 },
                { x: -1.5, z: -1.2 }, { x: 1.5, z: -1.2 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.8, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights
            const lightGeo = new THREE.BoxGeometry(0.5, 0.2, 0.1);
            const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0xffffaa });
            const leftLight = new THREE.Mesh(lightGeo, lightMat);
            leftLight.position.set(-0.8, 1.6, 1.6);
            carGroup.add(leftLight);

            const rightLight = new THREE.Mesh(lightGeo, lightMat);
            rightLight.position.set(0.8, 1.6, 1.6);
            carGroup.add(rightLight);

            return carGroup;
        }

        // --- Cars ---
        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);
        scene.add(redCar);
        scene.add(blueCar);

        // --- State ---
        let raceState = 'start'; // start, racing, finished
        let blueSpeed = 0.8;
        let redSpeed = 0.8;
        let blueOvertake = false;
        let redWin = false;
        let animationId;

        // --- Helpers ---
        const updateCamera = () => {
            // Smooth follow logic based on average position
            const targetZ = (redCar.position.z + blueCar.position.z) / 2;
            camera.position.z = targetZ + CAMERA_DISTANCE;
            camera.position.y = CAMERA_HEIGHT;
            camera.lookAt(targetZ, 0, 0);
        };

        const resetRace = () => {
            raceState = 'racing';
            blueSpeed = 0.8;
            redSpeed = 0.8;
            blueOvertake = false;
            redWin = false;

            // Reset positions
            redCar.position.z = START_Z;
            blueCar.position.z = START_Z;

            // Reset rotation (spin down)
            redCar.rotation.z = 0;
            blueCar.rotation.z = 0;
        };

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            animationId = requestAnimationFrame(animate);

            const dt = clock.getDelta();

            if (raceState === 'racing') {
                // Update positions
                redCar.position.z += redSpeed * dt;
                blueCar.position.z += blueSpeed * dt;

                // Rotation effect (faster spin = faster speed)
                redCar.rotation.x -= redSpeed * dt * 2;
                blueCar.rotation.x -= blueSpeed * dt * 2;

                // Logic: Blue leads, then Red overtakes
                if (!blueOvertake && blueCar.position.z > redCar.position.z + 1) {
                    blueOvertake = true;
                }

                if (blueOvertake) {
                    // Red accelerates
                    redSpeed = Math.min(redSpeed + 0.02 * dt, SPEED_LIMIT);

                    // Blue slows down slightly
                    blueSpeed = Math.max(blueSpeed - 0.005 * dt, 0.4);
                }

                // Check Finish Line
                const redFinished = redCar.position.z >= FINISH_LINE_Z;
                const blueFinished = blueCar.position.z >= FINISH_LINE_Z;

                if (redFinished && !redWin) {
                    redWin = true;
                    raceState = 'finished';
                }

                // Update Camera
                updateCamera();
            } 
            else if (raceState === 'finished') {
                // Bounce cars back to start
                redCar.position.z = Math.max(redCar.position.z - 0.5, START_Z);
                blueCar.position.z = Math.max(blueCar.position.z - 0.5, START_Z);
                updateCamera();
            }

            renderer.render(scene, camera);
        }

        // --- Event Listeners ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        window.addEventListener('keydown', (e) => {
            if (e.code === 'Space') {
                resetRace();
            }
        });

        // Start
        animate();

    </script>
</body>
</html>
```
